const fs = require('fs');
const buf = fs.readFileSync(0, 'utf8');
const tokens = buf.trim().split(/\s+/);
const N = +tokens[0];

const head = new Int32Array(N + 1).fill(-1);
const M = N - 1;
const nxt = new Int32Array(2 * M);
const to = new Int32Array(2 * M);
let ec = 0;
{
  let ptr = 1;
  for (let i = 0; i < M; i++) {
    const x = +tokens[ptr++], y = +tokens[ptr++];
    to[ec] = y; nxt[ec] = head[x]; head[x] = ec++;
    to[ec] = x; nxt[ec] = head[y]; head[y] = ec++;
  }
}

const dist = new Int32Array(N + 1);
const parent = new Int32Array(N + 1);
const q = new Int32Array(N + 1);

function bfs(src, ban) {
  dist.fill(-1);
  let qh = 0, qt = 0;
  dist[src] = 0; parent[src] = 0; q[qt++] = src;
  let far = src;
  while (qh < qt) {
    const u = q[qh++];
    if (dist[u] > dist[far]) far = u;
    for (let e = head[u]; e !== -1; e = nxt[e]) {
      const v = to[e];
      if (v === ban || dist[v] !== -1) continue;
      dist[v] = dist[u] + 1; parent[v] = u; q[qt++] = v;
    }
  }
  return far;
}

// Encontrar diâmetro D da árvore
const a = bfs(1, -1);
const b = bfs(a, -1);
const D = dist[b];

let ans;
if ((D & 1) === 0) {
  // Centro é um vértice c: todo par de diâmetro tem ambos os endpoints
  // a distância D/2 de c, em direções diferentes de c.
  const half = D >> 1;
  let c = b;
  for (let i = 0; i < half; i++) c = parent[c];
  let deg = 0;
  for (let e = head[c]; e !== -1; e = nxt[e]) deg++;
  const cntDir = new Int32Array(deg);
  const dir = new Int32Array(N + 1);
  dist.fill(-1);
  let qt = 0, qh = 0;
  dist[c] = 0; q[qt++] = c;
  let di = 0;
  for (let e = head[c]; e !== -1; e = nxt[e]) {
    const v = to[e];
    dist[v] = 1; dir[v] = di; q[qt++] = v; di++;
  }
  while (qh < qt) {
    const u = q[qh++];
    for (let e = head[u]; e !== -1; e = nxt[e]) {
      const v = to[e];
      if (dist[v] !== -1) continue;
      dist[v] = dist[u] + 1; dir[v] = dir[u]; q[qt++] = v;
    }
  }
  let T = 0, sq = 0;
  for (let v = 1; v <= N; v++) {
    if (dist[v] === half) { T++; cntDir[dir[v]]++; }
  }
  for (let i = 0; i < deg; i++) sq += cntDir[i] * cntDir[i];
  ans = (D + 1) + '\n' + ((T * T - sq) / 2);
} else {
  // Centro é uma aresta (c1, c2): todo par de diâmetro tem um endpoint
  // de cada lado dessa aresta, com dist(u,c1) + dist(v,c2) = D-1.
  const half = (D - 1) >> 1;
  let c2 = b;
  for (let i = 0; i < half; i++) c2 = parent[c2];
  const c1 = parent[c2];
  bfs(c1, c2);
  const cntA = new Int32Array(D + 1);
  for (let v = 1; v <= N; v++) if (dist[v] !== -1) cntA[dist[v]]++;
  bfs(c2, c1);
  const cntB = new Int32Array(D + 1);
  for (let v = 1; v <= N; v++) if (dist[v] !== -1) cntB[dist[v]]++;
  let count = 0;
  for (let t = 0; t <= D - 1; t++) count += cntA[t] * cntB[D - 1 - t];
  ans = (D + 1) + '\n' + count;
}

process.stdout.write(ans + '\n');
